\label{thma:classification}
    Suppose $\mathcal F$ is a finite depth, $C^2$ foliation. Then $\mathcal F$ forces closed orbits if and only if 
    \begin{enumerate}
        \item $\mathcal F$ contains a locally top-depth region that is not a topological product, or
        \item $\mathcal F$ is $C^0$-approximated by such foliations.
    \end{enumerate}
    If $\mathcal F$ does not force closed orbits, it admits a $C^1$ transverse aperiodic flow.

\label{lem:octopus}
    Let $U$ be an open saturated set of $\mathcal F$ on a compact manifold $M$. Then the completion $\widehat U$ admits an \textbf{\emph{octopus decomposition}} $\widehat U = N \cup A_1 \cup ... \cup A_n$, where $N$ is a sutured manifold carrying $\mathcal F_{\widehat U}$ such that $\partial_\pm N \subset \partial_\pm \widehat U$, and each $A_i$ is a foliated interval bundle over its noncompact boundary leaves $L_i^\pm$, which are contained in $\partial \widehat U$ and intersect $N$ along $\partial (\partial_\pm N)$. Moreover, $A_i$ and $N$ intersect along a component of $\partial_\pitchfork N$.

    If $\varphi$ is a flow transverse to $\mathcal F$, the octopus decomposition can be chosen so that $N$ is compatible with $\varphi_{\widehat U}$ and $\varphi$ defines a dynamical product on each $A_i$. We call such an octopus decomposition `\textbf{\emph{compatible with $\varphi$}}'.

Let $\mathcal F$ be finite depth. Then the following are equivalent:
    \begin{itemize}
        \item $\mathcal F$ is $C^2$-smoothable
        \item $\mathcal F$ is $C^\infty$-smoothable
        \item All junctures of all spirals of $\mathcal F$ are compactly supported.
    \end{itemize}

\label{lem:top depth is fibered}
    If $U$ is a locally top-depth component of a foliation $\mathcal{F}$, where each leaf in $U$ is homeomorphic to a surface $L$, then $\mathcal{F}\left.\right|_U$ fibers over $S^1$ with fiber $L$. 

    Conversely, if $U$ is a connected open saturated set of a finite depth foliation on which the foliation restricts to a fibration over $S^1$, then $U$ is a locally top-depth component.

\label{lem:depth1octopus}    Let $\varphi$ be a flow transverse to a foliation $\mathcal F$ and let $U$ be a locally top-depth component. Then there is an immersed, connected, sutured manifold $N$, carrying $\widehat{U}$ and compatible with $\varphi$, which is embedded away from $\partial_\pm N$. Moreover, $N$ satisfies the following properties:
    \begin{enumerate}
        \item $\partial_\pm N \subset \partial \widehat{U}$
        \item The pullback of $\mathcal{F}$ to $N$ is depth 1 with all depth 0 leaves contained in the boundary.
        \item The foliation by flowlines of $\varphi$ gives the structure of an interval bundle in the complement of $N$ in $U$. In particular, every orbit of $\varphi$ which enters $U$ outside of $N$ leaves $U$.
    \end{enumerate}

\label{lem:pluginsertion}
    Let $\varphi$ be a flow transverse to $\mathcal{F}$. Let $\gamma_1$ and $\gamma_2$ be two oriented simple closed curves in a leaf $L$ of $\mathcal{F}$ such that:
    \begin{enumerate}
        \item $\gamma_1$ has two-sided attracting holonomy, and
        \item $\gamma_1$ and $\gamma_2$ intersect positively and transversely at a single point.
    \end{enumerate}
    Then for any neighborhood $U$ of $\gamma_1 \cup \gamma_2$ in $M$ for which $\varphi$ is smooth, there is a modified Schweitzer plug insertion $i:P = P_{\alpha,x, \psi'} \to U$ such that the plugged flow $\varphi_P$ is transverse to $\mathcal F$. Moreover, if $C$ is any closed disk contained in $U \cap L$, then $i$ can be chosen so that all orbits passing through $C$ are trapped by $P$.

\label{lem:insertion1}
    Let $\varphi$ be a flow transverse to $\mathcal{F}$. Let $\gamma_1$ and $\gamma_2$ be two oriented simple closed curves in a leaf $L$ of $\mathcal{F}$ such that
    \begin{enumerate}
        \item $\gamma_1$ has attracting holonomy on the positive side, and
        \item $\gamma_1$ and $\gamma_2$ intersect positively and transversely at a single point $x$.
    \end{enumerate}
    Then for any neighborhood $U$ of $\gamma_1 \cup \gamma_2$ in $M$ for which $\varphi$ is smooth, there is a positive Schweitzer semiplug insertion $i:P = P^+_{\alpha, \psi} \to M$ into $\varphi$ such that 
    \begin{enumerate}
        \item the plugged flow $\varphi_P$ is transverse to $\mathcal{F}$,
        \item the image $i(P)$ is contained in $U$, 
        \item the image of negative boundary $i(\partial_-P^+_{\alpha, \psi})$ is contained in $L$, and
        \item the orbit of $\varphi$ through $x$ is trapped by $P$.
    \end{enumerate}
    If $\gamma_1$ in addition has attracting holonomy on the negative side, there is a Schweitzer plug insertion $i': P = P_{\alpha, \psi} \to M$ satisfying the first two conditions above.

\label{lem:pluginsertion again}
	Let $\varphi$ be a flow transverse to $\mathcal{F}$. Let $\gamma_1$ and $\gamma_2$ be two oriented simple closed curves in a leaf $L$ of $\mathcal{F}$ such that:
	\begin{enumerate}
		\item $\gamma_1$ has two-sided attracting holonomy, and
		\item $\gamma_1$ and $\gamma_2$ intersect positively and transversely at a single point.
	\end{enumerate}
	Then for any neighborhood $U$ of $\gamma_1 \cup \gamma_2$ in $M$ for which $\varphi$ is smooth, there is a modified Schweitzer plug insertion $i:P = P_{\alpha,x, \psi'} \to U$ such that the plugged flow $\varphi_P$ is transverse to $\mathcal F$. Moreover, if $C$ is any closed disk contained in $U \cap L$, then $i$ can be chosen so that all orbits passing through $C$ are trapped by $P$.

\label{prop:junctures capstone}
	Let $U$ be a base region of $\mathcal F$. Then the following dichotomy holds.
	\begin{enumerate}
		\item If $U$ has connecting (limit) junctures, then $\mathcal F$ can be approximated by fibrations in $U$.
		\item If $U$ does not have connecting (limit) junctures, then it contains a nonseparating curve of two-sided attracting holonomy or an annulus of attracting holonomy. 
	\end{enumerate}

Throughout, let $U$ be a base region of base depth $\ell$ of the foliation $\mathcal F$, and let $V_d$ be defined as in the lemma statement. 
	\begin{enumerate}
		\item Suppose $U$ were a product region of the form $L\times (0,1)$. By construction of $\check{\mathcal F}$, we must have that the foliation $\check{\mathcal F}\mid_U$ is by parallel copies of $L$. However, since $U$ is a topological product, we also have that the boundary leaves of $\widehat U$ in $\check{\mathcal F}$ are homeomorphic to $L$. Thus, $U$ is not a locally top depth component of $\check{\mathcal F}$, contradicting the definition of a base region.

		\item The foliation $\check{\mathcal F}$ is obtained inductively by replacing locally top-depth product regions with trivially foliated products. We work inductively in reverse: suppose $V$ is a locally top-depth product region, of $\mathcal F$, so $\widehat V \cong L \times [0, 1]$, with $\mathcal F$ restricting to a relative depth one foliation with no holonomy in the interior. Then the next step of the induction is obtained by replacing $\mathcal F$ in $V$ with the product foliation by copies of $L$. By Lemma \ref{lem:juncturesinproduct}, the reverse direction is given by shearing. 

		\item Let $\varphi$ be a flow transverse to $\mathcal F$ which defines a dynamical product on each topological product. Let $L_d$ be a depth $d$ leaf of $U$. Then since $U$ fibers over $S^1$, it is not hard to see that $\varphi$ defines a first return map on $L_d$, thereby giving a homeomorphism $\widehat{U \setminus L_d} \cong L_d \times [0, 1]$ in which $\mathcal F$ is transverse to the interval fibers. This shows that any connected component of a saturated set $V\subsetneq U$ is a product region. In particular, each connected component of $V_d$ is a product region. To see that it is open, observe that a limit of points lying in leaves of depth $k$ must be in a leaf of depth $\leq k$, and so the complement of $V_d$ is closed. Now the same argument as prior shows that each $V^i_d$ is obtained by iterated shearing. To see that $V^i_d$ is a mapping torus region, observe that in $V_d$, $\mathcal F$ is obtained by iterated shearing, and hence by replacing the topological product $V_{d+1}$ with a trivially foliated product, we obtained a foliation in which $V_d$ is a locally top-depth component. Therefore $V_d$ topologically fibers over $S^1$ with fibers the depth $d$ leaves.
	\end{enumerate}

\label{prop:junctures capstone again}
	Suppose $\mathcal F$ is finite depth and $C^2$, and let $U$ be a base region of $\mathcal F$. Then the following dichotomy holds.
	\begin{enumerate}
		\item If $U$ has connecting (limit) junctures, then $\mathcal F$ can be approximated by fibrations in $U$.
		\item If $U$ does not have connecting (limit) junctures, then it contains a nonseparating curve of two-sided attracting holonomy or an annulus of attracting holonomy. 
	\end{enumerate}

\label{thm:characterization again}
	Suppose $\mathcal F$ is finite depth and $C^2$. Then $\mathcal F$ forces closed orbits if and only if $\mathcal F$ is $C^0$-approximated by foliations containing locally top-depth components that are not product regions. 
	If $\mathcal F$ does not force closed orbits, it admits a $C^1$ transverse aperiodic flow.
